import type { Actor, Role } from "@/types/member";
import { ROLE_RANK } from "@/types/member";
import type {
  PermissionAction,
  PermissionDecision,
  PermissionResource,
} from "@/types/permission";

/**
 * The single authorization entry point for Taskflow.
 *
 * Every Server Action, service method, Route Handler and permission-sensitive
 * UI component funnels through `can()`. Nothing else may branch on
 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 *
 * Decision order:
 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 *   2. platform staff bypass
 *   3. role matrix lookup
 *   4. ownership escalations (authors edit their own issues/comments)
 */

/** Minimum role required for each action, before ownership escalations. */
export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
  "org:read": "viewer",
  "org:update": "admin",
  "org:delete": "owner",
  "org:manage_billing": "owner",
  "org:manage_flags": "admin",
  "member:read": "viewer",
  "member:invite": "admin",
  "member:update_role": "admin",
  "member:remove": "admin",
  "project:create": "member",
  "project:read": "viewer",
  "project:update": "member",
  "project:archive": "admin",
  "project:delete": "owner",
  "issue:create": "member",
  "issue:read": "viewer",
  "issue:update": "member",
  "issue:assign": "member",
  "issue:archive": "member",
  "issue:delete": "admin",
  "comment:create": "member",
  "comment:read": "viewer",
  "comment:update": "member",
  "comment:delete": "admin",
  "activity:read": "member",
  "activity:export": "admin",
  "notification:read": "viewer",
  "notification:manage": "viewer",
  "webhook:manage": "admin",
};

/** Actions an actor may perform on their own content regardless of role rank. */
const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
  "issue:update": true,
  "issue:archive": true,
  "comment:update": true,
  "comment:delete": true,
  "notification:manage": true,
};

function isOwnedByActor(
  actor: Actor,
  resource: PermissionResource,
): boolean {
  switch (resource.kind) {
    case "issue":
      return (
        resource.authorId === actor.userId ||
        resource.assigneeId === actor.userId
      );
    case "comment":
      return resource.authorId === actor.userId;
    case "project":
      return resource.leadId === actor.userId;
    case "notification":
      return resource.recipientId === actor.userId;
    case "member":
      return resource.targetUserId === actor.userId;
    default:
      return false;
  }
}

/**
 * Answers "may this actor perform this action on this resource?".
 *
 * @param actor    the authenticated principal, always scoped to one org
 * @param action   a member of the closed `PermissionAction` vocabulary
 * @param resource the object being acted on, discriminated on `kind`
 */
export function can(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): boolean {
  return explain(actor, action, resource).allowed;
}

/** Same decision as `can()`, but reports why — used by the settings UI. */
export function explain(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): PermissionDecision {
  const base = { action, resourceKind: resource.kind } as const;

  if (actor.orgId !== resource.orgId) {
    return { ...base, allowed: false, reason: "denied_cross_tenant" };
  }

  if (actor.isPlatformStaff === true) {
    return { ...base, allowed: true, reason: "granted_by_staff" };
  }

  const required = ROLE_MATRIX[action];
  if (required === undefined) {
    return { ...base, allowed: false, reason: "denied_unknown_action" };
  }

  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
    return { ...base, allowed: true, reason: "granted_by_role" };
  }

  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
    return { ...base, allowed: true, reason: "granted_by_ownership" };
  }

  return { ...base, allowed: false, reason: "denied_by_role" };
}

/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
export class PermissionDeniedError extends Error {
  readonly code = "forbidden" as const;

  constructor(
    readonly action: PermissionAction,
    readonly decision: PermissionDecision,
  ) {
    super(`Permission denied: ${action} on ${decision.resourceKind}`);
    this.name = "PermissionDeniedError";
  }
}

/** Throwing variant of `can()` for service-layer guard clauses. */
export function assertCan(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): void {
  const decision = explain(actor, action, resource);
  if (!decision.allowed) {
    throw new PermissionDeniedError(action, decision);
  }
}

/** Bulk evaluation used by navigation and toolbar components. */
export function canAll(
  actor: Actor,
  actions: readonly PermissionAction[],
  resource: PermissionResource,
): boolean {
  return actions.every((action) => can(actor, action, resource));
}

/**
 * Plan changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, wouldExceedLimit, getLimit
 */
import {
  getLimit,
  getPlanLimits,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, billingResource, requireFound } from "./_support";
import type {
  CancelSubscriptionInput,
  ChangePlanInput,
  UpdateSeatsInput,
} from "@/schemas/billing";
import type {
  BillingSummary,
  Invoice,
  LimitCheck,
  LimitedResource,
  PlanId,
  Subscription,
} from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The dimensions the billing page shows a meter for. */
const SUMMARY_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function getBillingSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<BillingSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(orgId),
    "Subscription",
    orgId,
  );

  const checks = await Promise.all(
    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
  );

  const limits = getPlanLimits(subscription.plan);

  return {
    orgId,
    subscription,
    checks,
    upcomingInvoiceCents:
      limits.priceCentsPerSeatMonthly *
      subscription.seats *
      (subscription.interval === "annual" ? 12 : 1),
  };
}

/**
 * The one place a quota is evaluated. Every guard elsewhere calls this rather
 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
 * exactly two files: `plan-limits.ts` and `usageFor()` below.
 */
export async function checkLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<LimitCheck> {
  const plan = await planFor(orgId);
  const used = await usageFor(orgId, resource);
  const limit = getLimit(plan, resource);

  return {
    resource,
    plan,
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: wouldExceedLimit(plan, resource, used, requested),
  };
}

/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await emit("billing.limit_exceeded", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: check.limit,
    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const currentPlan = await planFor(input.orgId);

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const subscription = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
  );

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  return subscriptionRepo.updateSeatCount(input.orgId, input.seats);
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (subscription) return subscription.plan;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  return org.plan;
}

/** Maps a quota dimension onto the counter that measures it. */
async function usageFor(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<number> {
  const usage = await usageRepo.getUsage(orgId);

  switch (resource) {
    case "seats":
      return usage.seatsUsed;
    case "projects":
      return usage.projectsUsed;
    case "issuesPerProject":
      return usage.issuesUsed;
    case "storageMb":
      return usage.storageMbUsed;
    case "webhooks":
      return webhookRepo.countEndpoints(orgId);
    case "apiRequestsPerHour":
      return 0;
  }
}

/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";
import type { IssueStatus, IssuePriority } from "./issue";
import type { Role } from "./member";
import type { PlanId, LimitedResource } from "./billing";
import type { FeatureFlagKey } from "./feature-flag";

/** Fields present on every event payload; the bus stamps them on `emit`. */
export interface EventEnvelope {
  readonly orgId: OrgId;
  readonly actorId: UserId | null;
  readonly occurredAt: IsoTimestamp;
}

/**
 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 * only way to introduce one — services, jobs and the webhook dispatcher all
 * derive their handler signatures from it.
 */
export interface TaskflowEventMap {
  "project.created": EventEnvelope & {
    projectId: ProjectId;
    name: string;
    slug: string;
  };
  "project.archived": EventEnvelope & {
    projectId: ProjectId;
    issuesArchived: number;
  };
  "project.restored": EventEnvelope & { projectId: ProjectId };
  "issue.created": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    title: string;
    assigneeId: UserId | null;
    priority: IssuePriority;
  };
  "issue.updated": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    changedFields: readonly string[];
  };
  "issue.status_changed": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    from: IssueStatus;
    to: IssueStatus;
  };
  "issue.assigned": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    previousAssigneeId: UserId | null;
    assigneeId: UserId;
  };
  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
  "issue.overdue": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    dueAt: IsoTimestamp;
    assigneeId: UserId | null;
  };
  "comment.created": EventEnvelope & {
    commentId: CommentId;
    issueId: IssueId;
    mentionedUserIds: readonly UserId[];
  };
  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
  "member.invited": EventEnvelope & { email: string; role: Role };
  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
  "member.role_changed": EventEnvelope & {
    memberId: MemberId;
    from: Role;
    to: Role;
  };
  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
  "billing.limit_exceeded": EventEnvelope & {
    resource: LimitedResource;
    limit: number;
    used: number;
  };
  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
  "search.reindex_requested": EventEnvelope & {
    subjectKind: "issue" | "comment" | "project";
    subjectId: string;
  };
  "webhook.delivery_requested": EventEnvelope & {
    eventType: string;
    payload: Readonly<Record<string, unknown>>;
  };
}

export type TaskflowEventType = keyof TaskflowEventMap;

export type TaskflowEventPayload<K extends TaskflowEventType> =
  TaskflowEventMap[K];

/** A handler registered with `subscribe()`. May be async; errors are isolated. */
export type EventHandler<K extends TaskflowEventType> = (
  payload: TaskflowEventPayload<K>,
) => void | Promise<void>;

/** Returned by `subscribe()`; calling it removes the handler. */
export type Unsubscribe = () => void;

/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}

import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const NOTIFICATION_KINDS = [
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
] as const;

export const notifications = sqliteTable(
  "notifications",
  {
    id: idColumn(),
    ...tenantColumns,
    recipientId: text("recipient_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    href: text("href").notNull(),
    actorId: text("actor_id"),
    readAt: text("read_at"),
    /** JSON array of `NotificationChannel`. */
    channels: text("channels").notNull().default('["in_app"]'),
    ...timestampColumns,
  },
  (table) => [
    index("notifications_org_recipient_idx").on(table.orgId, table.recipientId),
    index("notifications_org_read_idx").on(table.orgId, table.readAt),
  ],
);

export const notificationPreferences = sqliteTable(
  "notification_preferences",
  {
    ...tenantColumns,
    userId: text("user_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    inApp: integer("in_app", { mode: "boolean" }).notNull().default(true),
    email: integer("email", { mode: "boolean" }).notNull().default(true),
    digestOnly: integer("digest_only", { mode: "boolean" })
      .notNull()
      .default(false),
  },
  (table) => [
    uniqueIndex("notification_preferences_pk").on(
      table.orgId,
      table.userId,
      table.kind,
    ),
  ],
);

export type NotificationRow = typeof notifications.$inferSelect;
export type NewNotificationRow = typeof notifications.$inferInsert;
export type NotificationPreferenceRow =
  typeof notificationPreferences.$inferSelect;

/**
 * Audit-log writer and reader. Subscribes to the whole event bus and records one row per domain event.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, toCsv
 */
import { toCsv } from "@/lib/csv";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
