import { and, eq, isNull, or } from \"drizzle-orm\";
import { getDb, members, organizations, ownershipHandovers } from \"@/server/db\";
import { OwnershipHandoverError } from \"@/lib/errors\";
import { newId } from \"@/lib/id\";
import { toIsoTimestamp } from \"@/types/common\";
import { toOrganization } from \"@/server/repositories/_mappers\";
import { NotFoundError } from \"./_support\";
import type { OrgId, UserId } from \"@/types/common\";
import type { OwnershipHandover } from \"@/types/organization\";

const map = (row: typeof ownershipHandovers."'$inferSelect): OwnershipHandover => ({
  ...row, orgId: row.orgId as OrgId, fromUserId: row.fromUserId as UserId,
  toUserId: row.toUserId as UserId, createdAt: row.createdAt as OwnershipHandover["createdAt"],
  expiresAt: row.expiresAt as OwnershipHandover["expiresAt"], resolvedAt: row.resolvedAt as OwnershipHandover["resolvedAt"],
});
const pending = (orgId: OrgId) => getDb().select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
export function getPending(orgId: OrgId): OwnershipHandover | null {
  const row = pending(orgId);
  return row && row.expiresAt > new Date().toISOString() ? map(row) : null;
}
export function initiate(orgId: OrgId, from: UserId, to: UserId): OwnershipHandover {
  return getDb().transaction(tx => {
    const now = toIsoTimestamp(new Date());
    const current = tx.select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
    if (current && current.expiresAt > now) throw new OwnershipHandoverError("pending_exists");
    if (current) tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: current.expiresAt }).where(eq(ownershipHandovers.id, current.id)).run();
    const row = tx.insert(ownershipHandovers).values({ id: newId(), orgId, fromUserId: from, toUserId: to, status: "pending", createdAt: now, expiresAt: toIsoTimestamp(new Date(new Date(now).getTime() + 7 * 86400000)), resolvedAt: null }).returning().get();
    return map(row);
  });
}
export function resolve(orgId: OrgId, userId: UserId, action: "accepted" | "declined" | "canceled") {
  return getDb().transaction(tx => {
    const row = tx.select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
    if (!row || (action === "canceled" ? row.fromUserId !== userId : row.toUserId !== userId)) throw new OwnershipHandoverError("nothing_pending");
    const now = toIsoTimestamp(new Date());
    if (row.expiresAt <= now) throw new OwnershipHandoverError(action === "canceled" ? "nothing_pending" : "expired");
    let organization = null;
    const changes: { memberId: typeof members.$inferSelect.id; from: typeof members.$inferSelect.role; to: typeof members.$inferSelect.role }[] = [];
    if (action === "accepted") {
      const old = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, row.fromUserId), isNull(members.archivedAt), eq(members.status, "active"))).get();
      const next = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, row.toUserId), isNull(members.archivedAt), eq(members.status, "active"))).get();
      if (!old || !next) throw new NotFoundError("Member", !old ? row.fromUserId : row.toUserId);
      if (next.role !== "owner") {
        tx.update(members).set({ role: "owner", updatedAt: now }).where(eq(members.id, next.id)).run();
        changes.push({ memberId: next.id, from: next.role, to: "owner" });
      }
      organization = toOrganization(tx.update(organizations).set({ ownerId: row.toUserId, updatedAt: now }).where(eq(organizations.id, orgId)).returning().get());
      if (old.role === "owner") {
        tx.update(members).set({ role: "admin", updatedAt: now }).where(eq(members.id, old.id)).run();
        changes.push({ memberId: old.id, from: old.role, to: "admin" });
      }
    }
    const updated = tx.update(ownershipHandovers).set({ status: action, resolvedAt: now }).where(eq(ownershipHandovers.id, row.id)).returning().get();
    return { handover: map(updated), organization, changes };
  });
}
export function cancelForMember(orgId: OrgId, userId: UserId): void {
  const now = toIsoTimestamp(new Date());
  getDb().update(ownershipHandovers).set({ status: "canceled", resolvedAt: now }).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), or(eq(ownershipHandovers.fromUserId, userId), eq(ownershipHandovers.toUserId, userId)))).run();
}
