cat >> src/server/services/organization-service.ts <<'"'EOF'

/** Only the recorded owner can make or withdraw an offer. */
export async function assertRecordedOwner(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), \"Organization\", orgId);
  if (org.ownerId "'!== actor.userId) {
    throw new PermissionDeniedError("org:manage_billing", { action: "org:manage_billing", resourceKind: "organization", allowed: false, reason: "denied_by_role" });
  }
  return org;
}

export async function initiateOwnershipHandover(actor: Actor, orgId: OrgId, toUserId: UserId): Promise<OwnershipHandover> {
  const org = await assertRecordedOwner(actor, orgId);
  if (actor.userId === toUserId) throw new OwnershipHandoverError("self");
  const member = await memberRepo.findMember(orgId, toUserId);
  if (!member || member.status !== "active") throw new NotFoundError("Member", toUserId);
  const offer = handoverStore.initiate(orgId, actor.userId, toUserId);
  await notify(orgId, "ownership_handover", [toUserId], { title: "Workspace ownership offered", body: `You have been invited to take ownership of ${org.name}`, href: "/settings/members", actorId: actor.userId });
  return offer;
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return handoverStore.getPending(orgId);
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const result = handoverStore.resolve(orgId, actor.userId, "accepted");
  for (const change of result.changes) {
    await emit("member.role_changed", { ...envelope(orgId, actor.userId), memberId: change.memberId as MemberId, from: change.from, to: change.to });
  }
  await emit("organization.ownership_transferred", { ...envelope(orgId, actor.userId), fromUserId: result.handover.fromUserId, toUserId: result.handover.toUserId });
  return result.organization!;
}

export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  return handoverStore.resolve(orgId, actor.userId, "declined").handover;
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  await assertRecordedOwner(actor, orgId);
  return handoverStore.resolve(orgId, actor.userId, "canceled").handover;
}
